css:
:root {
  --bg: #0f111a;
  --panel: #181b28;
  --ink: #f0f2f5;
  --muted: #9ba1b0;
  --accent: #ff3366;
  --accent-dim: #3a1525;
  --line: #262b3d;
}

body {
  background-color: var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, sans-serif;
}

header, .logo-webplay .logo-texto {
  color: var(--ink);
}

.logo-webplay .logo-texto b {
  color: var(--accent);
}

.btn-feed, .profile-btn, .history-btn, .bottom-nav button {
  background-color: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
}

.bottom-nav button.ativa, .banner-btn {
  background-color: var(--accent);
  color: #fff;
}

.search input {
  background-color: var(--panel);
  color: var(--ink);
  border: 1px solid var(--line);
}

.card {
  background-color: var(--panel);
  border: 1px solid var(--line);
}

.card .meta .t {
  color: var(--ink);
}

.card .meta .y, .card-meta-tipo {
  color: var(--muted);
}

.card-tipo-badge {
  background-color: var(--accent-dim);
  color: var(--accent);
}

.bottom-nav {
  background-color: var(--panel);
  border-top: 1px solid var(--line);
}

.banner-titulo {
  color: var(--ink);
}

.streaming-mascote-topo {
  position: fixed;
  top: 54px;
  right: 8px;
  z-index: 9999;
  width: 24px;
  height: 24px;
  background: var(--accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 0 10px var(--accent);
  animation: mascotePulsar 1.5s infinite ease-in-out;
}

.streaming-mascote-topo::after {
  content: "🐾";
  font-size: 12px;
}

@keyframes mascotePulsar {
  0% {
    transform: scale(1);
    opacity: 0.9;
  }
  50% {
    transform: scale(1.25);
    opacity: 1;
    box-shadow: 0 0 18px var(--accent);
  }
  100% {
    transform: scale(1);
    opacity: 0.9;
  }
}
